head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40202";
scwin.sub_stkcertListApprovDd_Y = null;
scwin.sub_stkcertListApprovDd_M = null;
scwin.sub_stkcertListApprovDd_D = null;
scwin.sub_stkcertListDd_Y = null;
scwin.sub_stkcertListDd_M = null;
scwin.sub_stkcertListDd_D = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — corpUsrTpCd, isurCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40202.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "a_45", attr: "src", fn: function () { return "mailto:" + String(String((dma_pageContext.get("email") ?? ""))); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") !== '12' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '13' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '14' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '15' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '22' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '23' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '51' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '52' && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '62'  && (dma_pageContext.get("corpUsrTpCd") ?? "") !== '1E'); } }, { id: "c_when_19", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11'); } }, { id: "c_when_21", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21'); } }, { id: "c_when_23", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '61'); } }, { id: "c_when_25", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '12'); } }, { id: "c_when_27", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '16' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '17'); } }, { id: "c_when_29", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1F' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1G'); } }, { id: "c_when_31", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_when_33", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1A' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1B'); } }, { id: "c_when_35", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '22'); } }, { id: "c_when_37", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '31'); } }, { id: "c_when_39", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1C'); } }, { id: "c_otherwise_41", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '11') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '61') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '12') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '16' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '17') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1F' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1G') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1A' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1B') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '22') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '31') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1C'))); } }, { id: "if_corpUsrTpCd_2", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") !== '1E'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "a_45", fn: function () { return String(String((dma_pageContext.get("email") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Print_onclick
 * @description btn_Print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Print_onclick = function(e){
    try {
        scwin.print((String(((dma_pageContext.get("isurCd") ?? "")) == null ? '' : ((dma_pageContext.get("isurCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isurCd") ?? "")) == null ? '' : ((dma_pageContext.get("isurCd") ?? "")))),(String(((dma_pageContext.get("corpUsrTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("corpUsrTpCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("corpUsrTpCd") ?? "")) == null ? '' : ((dma_pageContext.get("corpUsrTpCd") ?? "")))))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40202.btn_Print_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_Print
 * @description Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_PrintReq") ? $c.util.getComponent("dma_PrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name print
 * @description print 처리
 * @param {String} _isurCd _isurCd
 * @param {String} _corpUsrTpCd _corpUsrTpCd
 * @returns {void}
 * @hidden N
 */
scwin.print = function (_isurCd, _corpUsrTpCd) {
    let rexName = "";
    if (_corpUsrTpCd === '11') {
        rexName = "RLDFIL00002";
    } else {
        if (_corpUsrTpCd === '19') {
            rexName = "RLDFIL00025";
        } else {
            if (_corpUsrTpCd === '21' || _corpUsrTpCd === '24') {
                rexName = "RLDFIL00003";
            } else {
                if (_corpUsrTpCd === '31') {
                    rexName = "RLDFIL00023";
                } else {
                    if (_corpUsrTpCd === '16' || _corpUsrTpCd === '17' || _corpUsrTpCd === '1A' || _corpUsrTpCd === '1B' || _corpUsrTpCd === '1C' || _corpUsrTpCd === '1F' || _corpUsrTpCd === '1G') {
                        rexName = "RLDFIL00024";
                    } else {
                        if (_corpUsrTpCd === '61') {
                            rexName = "RLDFIL00035";
                        } else {
                            if (_corpUsrTpCd === '32') {
                                rexName = "RLDFIL00044";
                            }
                        }
                    }
                }
            }
        }
    }
    $.ajax({ type: "POST", async: false, url: "/outer/reportPrint.do?method=registerNewReport&isurCd=" + _isurCd + "&corpUsrTpCd=" + _corpUsrTpCd, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_PrintReq').set('ncomNm', result.comNm);
                if (result.stkcertListApprovDd) {
                    const sub_stkcertListApprovDd = result.stkcertListApprovDd;
                    scwin.sub_stkcertListApprovDd_Y = sub_stkcertListApprovDd.substring(0, 4);
                    scwin.sub_stkcertListApprovDd_M = sub_stkcertListApprovDd.substring(4, 6);
                    scwin.sub_stkcertListApprovDd_D = sub_stkcertListApprovDd.substring(6, 8);
                    $c.util.getComponent('dma_PrintReq').set('nstkcertListApprovDd', scwin.sub_stkcertListApprovDd_Y + "년 " + scwin.sub_stkcertListApprovDd_M + "월 " + scwin.sub_stkcertListApprovDd_D + "일");
                } else {
                    $c.util.getComponent('dma_PrintReq').set('nstkcertListApprovDd', result.stkcertListApprovDd);
                }
                if (result.stkcertListDd) {
                    const sub_stkcertListDd = result.stkcertListDd;
                    scwin.sub_stkcertListDd_Y = sub_stkcertListDd.substring(0, 4);
                    scwin.sub_stkcertListDd_M = sub_stkcertListDd.substring(4, 6);
                    scwin.sub_stkcertListDd_D = sub_stkcertListDd.substring(6, 8);
                    $c.util.getComponent('dma_PrintReq').set('nstkcertListDd', scwin.sub_stkcertListDd_Y + "년 " + scwin.sub_stkcertListDd_M + "월 " + scwin.sub_stkcertListDd_D + "일");
                } else {
                    $c.util.getComponent('dma_PrintReq').set('nstkcertListDd', result.stkcertListDd);
                }
                $c.util.getComponent('dma_PrintReq').set('nisurCd', result.isurCd);
                $c.util.getComponent('dma_PrintReq').set('nmainAddr', result.mainAddr);
                $c.util.getComponent('dma_PrintReq').set('nzipCd', result.zipCd);
                $c.util.getComponent('dma_PrintReq').set('ncorpTelNo', result.corpTelNo);
                $c.util.getComponent('dma_PrintReq').set('nhomePage', result.homePage);
                $c.util.getComponent('dma_PrintReq').set('ncorpUsrNm', result.corpUsrNm);
                $c.util.getComponent('dma_PrintReq').set('nusrBelngDepNm', result.usrBelngDepNm);
                $c.util.getComponent('dma_PrintReq').set('njobTitlNm', result.jobTitlNm);
                $c.util.getComponent('dma_PrintReq').set('ntelNo', result.telNo);
                $c.util.getComponent('dma_PrintReq').set('nemail', result.email);
                $c.util.getComponent('dma_PrintReq').set('nceoNm', result.ceoNm);
                $c.util.getComponent('dma_PrintReq').set('nTempleteCd', rexName);
                await scwin.tx_fn_Print();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};
